const input = $input.first().json;

// Change this if your AI node uses a different field
let raw = input.output;

// If the AI returned an object already, keep it
if (typeof raw === 'object' && raw !== null) {
  return [
    {
      json: raw
    }
  ];
}

// If it returned a JSON string, parse it
if (typeof raw === 'string') {
  raw = raw.trim();

  // Remove markdown code fences if the model added them
  raw = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    const parsed = JSON.parse(raw);

    // Handle the specific case where JSON.parse
    // produces another JSON string
    if (typeof parsed === 'string') {
      return [
        {
          json: JSON.parse(parsed)
        }
      ];
    }

    return [
      {
        json: parsed
      }
    ];

  } catch (error) {
    throw new Error(
      `Production Planner returned invalid JSON: ${error.message}`
    );
  }
}

throw new Error('Production Planner returned no usable JSON');

// Turns the planner's text_to_image array into one item per prompt 
const list = $('Format Raw Json').first().json.production.text_to_image|| [];
return list.map(item => ({ json: item }));

// Guarantee images are in sequence order
const imgs = [...$input.first().json.data].sort((a, b) => a.sequence - b.sequence);
return [{ json: { data: imgs } }];

// One item per video clip, each matched to its source image
const row = $input.first().json;

const clips = row.image_to_video || [];
let images = row.images || [];
if (typeof images === 'string') images = JSON.parse(images);

// image_url may be a real string, or a stringified array like '["https://..."]'
const cleanUrl = (u) => {
  if (Array.isArray(u)) return u[0] ?? null;
  if (typeof u === 'string' && u.trim().startsWith('[')) {
    try { return JSON.parse(u)[0] ?? null; } catch { return u; }
  }
  return u ?? null;
};

// Normalize images; sequence falls back to array position (= generation order)
images = images.map((img, i) => ({
  ...img,
  scene_id: String(img.scene_id),
  image_url: cleanUrl(img.image_url),
  sequence: img.sequence ?? i + 1,
}));

const byId = {};
const byScene = {};
for (const img of images) {
  byId[img.image_id] = img;
  (byScene[img.scene_id] ||= []).push(img);
}
for (const id in byScene) byScene[id].sort((a, b) => a.sequence - b.sequence);

return clips.map((clip, i) => {
  const sceneImgs = byScene[String(clip.scene_id)] || [];
  const exact = byId[clip.source_image_id];
  const source = exact || sceneImgs[0] || null;

  return {
    json: {
      ...clip,
      clip_sequence: i + 1,
      production_id: row.production_id,
      source_image_id: source?.image_id ?? clip.source_image_id,
      source_image_url: source?.image_url ?? null,
      scene_image_urls: sceneImgs.map((s) => s.image_url),
      image_match: exact ? 'exact' : source ? 'scene_fallback' : 'MISSING',
    },
  };
});

// Guarantee images are in sequence order
const vids = [...$input.first().json.data].sort((a, b) => a.sequence - b.sequence);
return [{ json: { data: vids } }];

// ---- EDIT THESE ----
const SUPABASE_URL = 'https://YOUR_PROJECT_REF.supabase.co'; // your Supabase project URL
const BUCKET = 'production-assets';                          // public Storage bucket

const arr = (v) => { if (v == null) return []; if (typeof v === 'string') { try { v = JSON.parse(v); } catch { return []; } } return Array.isArray(v) ? v : [v]; };
const obj = (v) => { if (typeof v === 'string') { try { return JSON.parse(v); } catch { return {}; } } return v || {}; };
const row = $input.first().json;
const list = arr(row.sfx).filter(s => s && s.description);

// no SFX planned -> let the flow continue
if (!list.length) return [{ json: { skip: true, production_id: row.production_id, data: [] } }];

return list.map((s, i) => {
  const path = `${row.production_id}/sfx/${s.sfx_id}.mp3`;
  return { json: {
    ...s,
    production_id: row.production_id,
    sequence: i + 1,
    sfx_duration: Math.min(30, Math.max(0.5, Number(s.duration_seconds) || 2)), // ElevenLabs: 0.5-30s
    upload_url: `${SUPABASE_URL}/storage/v1/object/${BUCKET}/${path}`,
    public_url: `${SUPABASE_URL}/storage/v1/object/public/${BUCKET}/${path}`,
  } };
});

// Guarantee SFX are in sequence order
const items = [...$input.first().json.data].sort((a, b) => a.sequence - b.sequence);
return [{ json: { data: items } }];

const arr = (v) => { if (v == null) return []; if (typeof v === 'string') { try { v = JSON.parse(v); } catch { return []; } } return Array.isArray(v) ? v : [v]; };
const obj = (v) => { if (typeof v === 'string') { try { return JSON.parse(v); } catch { return {}; } } return v || {}; };
const one = (u) => { if (Array.isArray(u)) return u[0] ?? null; if (typeof u === 'string' && u.trim().startsWith('[')) { try { return JSON.parse(u)[0] ?? null; } catch { return u; } } return u ?? null; };

const row = $input.first().json;
const plan = arr(row.image_to_video);
const planVoice = arr(row.voice);
const videos = arr(row.videos).map(v => ({ ...v, video_url: one(v.video_url) })).filter(v => v.video_url)
  .sort((a, b) => (a.sequence ?? 0) - (b.sequence ?? 0));
const voices = arr(row.voices).filter(v => v.audio_url).sort((a, b) => (a.sequence ?? 0) - (b.sequence ?? 0));
const sfx = arr(row.sfx_audio).filter(s => s.audio_url);
const music = obj(row.music);
const sound = obj(row.sound);
const fmt = obj(row.format);

if (!videos.length) throw new Error('Editing: no completed video clips found in the videos column');

// 1) video track: clips back to back, each trimmed to its planned length
const plannedLen = {}; plan.forEach(c => { plannedLen[c.clip_id] = Number(c.duration_seconds) || 5; });
const sceneStart = {};
let cursor = 0;
const videoClips = videos.map(v => {
  const length = plannedLen[v.clip_id] || 5;
  const start = cursor;
  if (sceneStart[v.scene_id] === undefined) sceneStart[v.scene_id] = start;
  cursor += length;
  return { asset: { type: 'video', src: v.video_url, volume: 0 }, start, length };
});
const total = cursor;

// 2) voice track: starts at its scene; several segments in one scene follow each other
const estLen = {}; planVoice.forEach(v => { estLen[v.voice_id] = Number(v.estimated_duration_seconds) || 2; });
const sceneOffset = {};
const voiceClips = voices.map(v => {
  const base = sceneStart[v.scene_id] ?? 0;
  const off = sceneOffset[v.scene_id] || 0;
  sceneOffset[v.scene_id] = off + (estLen[v.voice_id] || 2);
  return { asset: { type: 'audio', src: v.audio_url, volume: 1 }, start: base + off, length: 'auto' };
});

// 3) SFX track: start_seconds treated as time in the whole ad (use base + start_seconds if yours are per scene)
const sfxClips = sfx.map(s => ({
  asset: { type: 'audio', src: s.audio_url, volume: 0.6 },
  start: Number(s.start_seconds) || (sceneStart[s.scene_id] ?? 0),
  length: 'auto',
}));

// 4) music track under everything
const musicClips = music.audio_url
  ? [{ asset: { type: 'audio', src: music.audio_url, volume: Number(music.volume ?? sound.volume ?? 0.22) }, start: 0, length: total }]
  : [];

const tracks = [{ clips: videoClips }];
if (voiceClips.length) tracks.push({ clips: voiceClips });
if (sfxClips.length) tracks.push({ clips: sfxClips });
if (musicClips.length) tracks.push({ clips: musicClips });

const edit = {
  timeline: { background: '#000000', tracks },
  output: { format: 'mp4', resolution: 'hd', aspectRatio: fmt.aspect_ratio || '9:16' },
};

return [{ json: { production_id: row.production_id, total_seconds: total, edit } }];

// ---- EDIT THESE ----
const SUPABASE_URL = 'https://YOUR_PROJECT_REF.supabase.co'; // your Supabase project URL
const BUCKET = 'production-assets';                          // public Storage bucket
const ELEVENLABS_VOICE_ID = '21m00Tcm4TlvDq8ikWAM';          // your ElevenLabs voice id

const arr = (v) => { if (v == null) return []; if (typeof v === 'string') { try { v = JSON.parse(v); } catch { return []; } } return Array.isArray(v) ? v : [v]; };
const row = $input.first().json;
const list = arr(row.voice).filter(v => v && v.text);

// no voice planned -> let the flow continue
if (!list.length) return [{ json: { skip: true, production_id: row.production_id, data: [] } }];

return list.map((v, i) => {
  const path = `${row.production_id}/voice/${v.voice_id}.mp3`;
  return { json: {
    ...v,
    production_id: row.production_id,
    sequence: i + 1,
    elevenlabs_voice_id: ELEVENLABS_VOICE_ID,
    upload_url: `${SUPABASE_URL}/storage/v1/object/${BUCKET}/${path}`,
    public_url: `${SUPABASE_URL}/storage/v1/object/public/${BUCKET}/${path}`,
  } };
});

// Guarantee SFX are in sequence order
const items = [...$input.first().json.data].sort((a, b) => a.sequence - b.sequence);
return [{ json: { data: items } }];
